pm.test('Fact text is present', () => {
    const { fact } = pm.response.json();
    pm.expect(fact).to.be.a('string').and.match(/\S/);
});

pm.test('Reported length matches the text', () => {
    const { fact, length } = pm.response.json();
    pm.expect(length).to.be.above(0).and.equal(fact.length);
});

pm.test('Fact respects max_length', () => {
    const maxLength = Number(pm.request.url.query.get('max_length'));
    pm.expect(pm.response.json().fact.length).to.be.at.most(maxLength);
});

