pm.test('Page respects the requested limit', () => {
    const limit = Number(pm.request.url.query.get('limit'));
    const { data } = pm.response.json();

    pm.expect(data).to.be.an('array');
    pm.expect(data.length).to.be.within(1, limit);
});

pm.test('Each fact has text and the correct length', () => {
    for (const { fact, length } of pm.response.json().data) {
        pm.expect(fact).to.be.a('string').and.match(/\S/);
        pm.expect(length).to.equal(fact.length);
    }
});

pm.test('First-page range matches the returned records', () => {
    const { current_page, from, to, data } = pm.response.json();

    pm.expect(current_page).to.equal(1);
    pm.expect(from).to.equal(1);
    pm.expect(to).to.equal(data.length);
});

