pm.test('Page respects the requested limit', () => {
    const limit = Number(pm.request.url.query.get('limit'));
    const { data } = pm.response.json();

    pm.expect(data).to.be.an('array');
    pm.expect(data.length).to.be.within(1, limit);
});

pm.test('Each breed has a name', () => {
    for (const { breed } of pm.response.json().data) {
        pm.expect(breed).to.be.a('string').and.match(/\S/);
    }
});

pm.test('Breed details are strings', () => {
    const fields = ['country', 'origin', 'coat', 'pattern'];

    for (const breed of pm.response.json().data) {
        for (const field of fields) {
            pm.expect(breed[field], field).to.be.a('string');
        }
    }
});

